const items = $input.all();
const today = new Date();
const dormantCustomers = [];

for (const item of items) {
  const lastPurchase = new Date(item.json.last_purchase_date);
  const daysSince = Math.floor((today - lastPurchase) / (1000 * 60 * 60 * 24));

  // Target 60-90 day dormant customers not already in reengagement
  const alreadySent = item.json.reengagement_sent && item.json.reengagement_sent !== '';

  if (daysSince >= 60 && daysSince <= 90 && !alreadySent) {
    dormantCustomers.push({
      json: {
        ...item.json,
        days_dormant: daysSince,
        customer_value: item.json.total_purchases || 1
      }
    });
  }
}

// Sort by customer value (highest value first)
dormantCustomers.sort((a, b) => b.json.customer_value - a.json.customer_value);

console.log(`Found ${dormantCustomers.length} dormant customers for re-engagement`);
return dormantCustomers;
